This Terraform configuration deploys an AWS Lightsail PostgreSQL managed database. It enables `apply_immediately = true`, so supported configuration changes are applied immediately instead of waiting for the configured maintenance window. The configuration includes default variables, provider setup, password generation, the Lightsail PostgreSQL database resource, and useful outputs.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lightsail PostgreSQL database will be created."
  type        = string
  default     = "us-east-1"
}

variable "database_name" {
  description = "Name of the Lightsail relational database instance."
  type        = string
  default     = "lightsail-postgres-db"
}

variable "master_database_name" {
  description = "Name of the default PostgreSQL database to create."
  type        = string
  default     = "appdb"
}

